import{c as r,Q as e,j as t,m as i}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"RO3「全民领土战」玩法实机预告片发布","description":"RO3 发布领土战玩法预告，千人攻城、领地争霸，公会战系统全面升级","frontmatter":{"title":"RO3「全民领土战」玩法实机预告片发布","description":"RO3 发布领土战玩法预告，千人攻城、领地争霸，公会战系统全面升级"},"headers":[],"relativePath":"news/territory-war-202603.md","filePath":"news/territory-war-202603.md","lastUpdated":1779287780000}'),l={name:"news/territory-war-202603.md"};function o(n,a,s,d,h,c){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ro3「全民领土战」玩法实机预告片发布" tabindex="-1">RO3「全民领土战」玩法实机预告片发布 <a class="header-anchor" href="#ro3「全民领土战」玩法实机预告片发布" aria-label="Permalink to &quot;RO3「全民领土战」玩法实机预告片发布&quot;">​</a></h1><p>日期：2026-03 | 来源：官方/玩家社群</p><h2 id="领土战预告片公开" tabindex="-1">领土战预告片公开 <a class="header-anchor" href="#领土战预告片公开" aria-label="Permalink to &quot;领土战预告片公开&quot;">​</a></h2><p>RO3 官方发布了「全民领土战」玩法实机预告片，展示了游戏中最宏大的 PVP 内容——领地争霸战。</p><h2 id="领土战核心玩法" tabindex="-1">领土战核心玩法 <a class="header-anchor" href="#领土战核心玩法" aria-label="Permalink to &quot;领土战核心玩法&quot;">​</a></h2><ul><li><strong>规模</strong>：支持大规模公会联盟对战</li><li><strong>地图</strong>：每个领地拥有独特地形和战略要点</li><li><strong>器械</strong>：攻城车、云梯、炮台等攻城器械</li><li><strong>策略</strong>：粮草运输、公会外交、战术部署</li></ul><h2 id="赛季制配合" tabindex="-1">赛季制配合 <a class="header-anchor" href="#赛季制配合" aria-label="Permalink to &quot;赛季制配合&quot;">​</a></h2><p>领土战与游戏赛季制深度绑定：</p><ul><li>每个赛季开启新的领土争夺</li><li>赛季奖励包含专属称号、稀有装备、限定外观</li><li>占领领地的公会获得该区域的专属收益</li></ul><h2 id="玩家反响" tabindex="-1">玩家反响 <a class="header-anchor" href="#玩家反响" aria-label="Permalink to &quot;玩家反响&quot;">​</a></h2><p>预告片发布后在玩家社群引起热议，许多老 RO 玩家对 GVG 系统的全面升级表示期待，特别是千人同屏攻城战的实现。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li><a href="https://www.bilibili.com/video/BV1S88yzvEar/" target="_blank" rel="noreferrer">Bilibili 实机预告片</a></li><li>官方 Discord 社群公告</li></ul>',13)])])}const _=r(l,[["render",o]]);export{p as __pageData,_ as default};
